-- 06_pages.sql — seo_website_page_master (SmileScape, MINIMAL STUB) — 722 pages.
-- page_fingerprint='smilescape-{node}'. URLs/CPT/T-template/parent deferred (need keyword research).
-- fingerprint/display auto by trigger. cluster_id set authoritatively from entity below.
on conflict (page_fingerprint) do nothing;

-- authoritative cluster: page inherits its primary entity's topic_cluster_id
update public.seo_website_page_master p set cluster_id = g.topic_cluster_id
  from public.seo_entity_graph g
  where p.brand_id='smile-scape-clinic' and p.primary_entity_fp is not null
    and g.entity_fingerprint = p.primary_entity_fp;

-- validation
select count(*) total, count(primary_entity_fp) with_entity, count(cluster_id) with_cluster
from public.seo_website_page_master where brand_id='smile-scape-clinic';
